SELECT w.w_warehouse_name, cd.cd_gender, COALESCE(SUM(ss.ss_net_profit), 0) AS total_sales_profit, COALESCE(SUM(cr.cr_net_loss), 0) AS total_return_loss, COALESCE(SUM(ss.ss_net_profit), 0) - COALESCE(SUM(cr.cr_net_loss), 0) AS net_gain, DENSE_RANK() OVER (ORDER BY COALESCE(SUM(cr.cr_net_loss), 0) DESC) AS loss_rank, CASE WHEN COALESCE(SUM(cr.cr_net_loss), 0) > 10000 THEN 'High Loss' ELSE 'Low Loss' END AS loss_category FROM warehouse w LEFT JOIN catalog_returns cr ON cr.cr_warehouse_sk = w.w_warehouse_sk LEFT JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN store_sales ss ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY w.w_warehouse_name, cd.cd_gender HAVING COALESCE(SUM(ss.ss_net_profit), 0) > 0 OR COALESCE(SUM(cr.cr_net_loss), 0) > 0 ORDER BY net_gain DESC LIMIT 15
